import{_ as h,o as t,c as o,a2 as i}from"./chunks/framework.mRCPFc5l.js";const q=JSON.parse('{"title":"Vì sao lúc bảo &quot;học&quot;, lúc bảo &quot;test&quot;, lúc bảo &quot;nghỉ&quot;","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/hoc-test-nghi.md","filePath":"decisions/hoc-test-nghi.md"}'),a={name:"decisions/hoc-test-nghi.md"};function c(g,n,u,e,l,r){return t(),o("div",null,[...n[0]||(n[0]=[i('<h1 id="vi-sao-luc-bao-quot-hoc-quot-luc-bao-quot-test-quot-luc-bao-quot-nghi-quot" tabindex="-1">Vì sao lúc bảo &quot;học&quot;, lúc bảo &quot;test&quot;, lúc bảo &quot;nghỉ&quot; <a class="header-anchor" href="#vi-sao-luc-bao-quot-hoc-quot-luc-bao-quot-test-quot-luc-bao-quot-nghi-quot" aria-label="Permalink to &quot;Vì sao lúc bảo &amp;quot;học&amp;quot;, lúc bảo &amp;quot;test&amp;quot;, lúc bảo &amp;quot;nghỉ&amp;quot;&quot;">​</a></h1><p>Trên trang này# Vì sao lúc bảo &quot;học&quot;, lúc bảo &quot;test&quot;, lúc bảo &quot;nghỉ&quot; <a href="#vi-sao-luc-bao-hoc-luc-bao-test-luc-bao-nghi">​</a> Ba lời khuyên trông rất khác nhau, nhưng chúng đến từ cùng một phép tính. Cái quyết định không phải learner giỏi hay kém, mà là <strong>hệ thống đang thiếu cái gì</strong>.</p><h2 id="ba-tinh-huong-ba-cau-tra-loi-​" tabindex="-1">Ba tình huống, ba câu trả lời <a href="#ba-tinh-huong-ba-cau-tra-loi">​</a> <a class="header-anchor" href="#ba-tinh-huong-ba-cau-tra-loi-​" aria-label="Permalink to &quot;Ba tình huống, ba câu trả lời [​](#ba-tinh-huong-ba-cau-tra-loi)&quot;">​</a></h2><h3 id="khi-he-thong-bao-hoc-​" tabindex="-1">Khi hệ thống bảo &quot;học&quot; <a href="#khi-he-thong-bao-hoc">​</a> <a class="header-anchor" href="#khi-he-thong-bao-hoc-​" aria-label="Permalink to &quot;Khi hệ thống bảo &quot;học&quot; [​](#khi-he-thong-bao-hoc)&quot;">​</a></h3><p>Điều kiện: có bằng chứng rõ ràng rằng learner còn hụt ở một phần, và phần đó đáng học ngay bây giờ. Cụ thể hơn: mức vững thấp, <strong>và</strong> độ chắc chắn cao — nghĩa là hệ thống đã đủ dữ liệu để biết chắc đây là lỗ hổng thật, không phải một ngày làm bài tệ.</p><h3 id="khi-he-thong-bao-đo-lai-​" tabindex="-1">Khi hệ thống bảo &quot;đo lại&quot; <a href="#khi-he-thong-bao-đo-lai">​</a> <a class="header-anchor" href="#khi-he-thong-bao-đo-lai-​" aria-label="Permalink to &quot;Khi hệ thống bảo &quot;đo lại&quot; [​](#khi-he-thong-bao-đo-lai)&quot;">​</a></h3><p>Điều kiện: <strong>hệ thống không biết đủ để quyết định</strong>. Đây là tình huống hay bị hiểu nhầm nhất. Một đề xuất &quot;đo&quot; không có nghĩa là &quot;hệ thống nghi ngờ con&quot;. Nó có nghĩa: mức vững đang thấp <em>nhưng</em> độ chắc chắn cũng thấp — có thể con vẫn ổn, chỉ là chưa có bằng chứng gần đây. Trong tình huống đó, giao một chương học lại là canh bạc: nếu hoá ra con vẫn vững, cả buổi học đó là lãng phí. Hỏi hai câu trước rồi quyết định rẻ hơn nhiều. Rất thường xuyên, hai câu đó đủ để nâng ước lượng từ 0.55 lên 0.88 ngay lập tức — và learner vừa tiết kiệm được một buổi học không cần thiết.</p><h3 id="khi-he-thong-bao-nghi-​" tabindex="-1">Khi hệ thống bảo &quot;nghỉ&quot; <a href="#khi-he-thong-bao-nghi">​</a> <a class="header-anchor" href="#khi-he-thong-bao-nghi-​" aria-label="Permalink to &quot;Khi hệ thống bảo &quot;nghỉ&quot; [​](#khi-he-thong-bao-nghi)&quot;">​</a></h3><p>Ba nguyên nhân khác nhau: <strong>Quá tải.</strong> Hoàn cảnh cho thấy learner đang ốm, kiệt sức, hoặc vừa qua một giai đoạn căng. Học tiếp trong trạng thái này tạo ra bằng chứng nhiễu và ký ức kém. <strong>Lợi ích thêm quá thấp.</strong> Learner đã học rất nhiều hôm nay. Giờ thứ tư gần như không thêm được gì, trong khi làm tăng khả năng chán và bỏ. <strong>Đã đạt mục tiêu hôm nay.</strong> Phần đáng làm nhất đã xong. Học thêm cho &quot;chắc&quot; thường là học lại thứ đã chắc. Vì sao &quot;nghỉ&quot; là một lời khuyên nghiêm túc Một hệ thống chỉ biết đề xuất học thêm sẽ luôn đề xuất học thêm. Nó không có cách nào nói &quot;hôm nay đủ rồi&quot; — và điều đó biến nó thành một công cụ tạo áp lực, dù không ai thiết kế nó với ý định đó.</p><h2 id="bang-bon-o-quyet-đinh-phan-lon-moi-thu-​" tabindex="-1">Bảng bốn ô quyết định phần lớn mọi thứ <a href="#bang-bon-o-quyet-đinh-phan-lon-moi-thu">​</a> <a class="header-anchor" href="#bang-bon-o-quyet-đinh-phan-lon-moi-thu-​" aria-label="Permalink to &quot;Bảng bốn ô quyết định phần lớn mọi thứ [​](#bang-bon-o-quyet-đinh-phan-lon-moi-thu)&quot;">​</a></h2><p>Độ chắc chắn thấpĐộ chắc chắn cao<strong>Mức vững thấp****Đo lại</strong> — chưa biết đủ<strong>Học</strong> — lỗ hổng đã rõ<strong>Mức vững cao****Đo xác nhận</strong> — có vẻ ổn, chưa chắc<strong>Đi tiếp</strong> — hoặc ôn nếu đang mờÔ trên bên trái là chỗ Nemo12 tiết kiệm được nhiều thời gian nhất cho learner. Phản xạ thông thường khi thấy chỉ số thấp là <em>bắt học lại</em>. Phản xạ đúng là <em>kiểm tra cho chắc trước đã</em>.</p><h2 id="ty-le-đoi-theo-thoi-gian-con-lai-​" tabindex="-1">Tỷ lệ đổi theo thời gian còn lại <a href="#ty-le-đoi-theo-thoi-gian-con-lai">​</a> <a class="header-anchor" href="#ty-le-đoi-theo-thoi-gian-con-lai-​" aria-label="Permalink to &quot;Tỷ lệ đổi theo thời gian còn lại [​](#ty-le-đoi-theo-thoi-gian-con-lai)&quot;">​</a></h2><p>Cùng một learner, cùng một mức kiến thức, nhưng khoảng cách tới kỳ thi đổi thì tỷ lệ giữa ba loại cũng đổi: Còn bao lâuNghiêng về8 thángHọc phần mới, xây nền rộng3 thángCân bằng học và ôn3 tuầnÔn, nhớ lại, đo — ít học phần mới3 ngàyGần như chỉ nhớ lại phần chắc chắn có trong đề, ngủ đủTỷ lệ này <strong>không được cài cứng</strong>. Nó được tính ra từ mục tiêu, thời gian còn lại, và mức sẵn sàng hiện tại. Learner còn 3 tuần nhưng đã rất sẵn sàng vẫn có thể học phần mới; learner còn 8 tháng nhưng hổng nền nghiêm trọng vẫn dành phần lớn thời gian để vá.</p><h2 id="khi-thoi-gian-it-hon-du-kien-​" tabindex="-1">Khi thời gian ít hơn dự kiến <a href="#khi-thoi-gian-it-hon-du-kien">​</a> <a class="header-anchor" href="#khi-thoi-gian-it-hon-du-kien-​" aria-label="Permalink to &quot;Khi thời gian ít hơn dự kiến [​](#khi-thoi-gian-it-hon-du-kien)&quot;">​</a></h2><p>Nếu learner chỉ có 15 phút thay vì 50 phút như thường lệ, hệ thống không cắt bài làm đôi. Nó chọn lại từ đầu: <strong>việc gì có giá trị cao nhất trên mỗi phút?</strong> Câu trả lời thường không phải &quot;một phần ba của bài dự định&quot;, mà là một việc hoàn toàn khác — thường là một lần nhớ lại ngắn ở một phần đang mờ.</p><h2 id="đieu-gia-đinh-nen-biet-​" tabindex="-1">Điều gia đình nên biết <a href="#đieu-gia-đinh-nen-biet">​</a> <a class="header-anchor" href="#đieu-gia-đinh-nen-biet-​" aria-label="Permalink to &quot;Điều gia đình nên biết [​](#đieu-gia-đinh-nen-biet)&quot;">​</a></h2><p>Khi hệ thống đề xuất một thứ trông lạ — ôn lại phần con đã học rất kỹ, hoặc bảo nghỉ khi bạn thấy con còn thời gian — bạn <strong>hỏi được lý do</strong>. Mỗi gợi ý đều lưu căn cứ: mức vững lịch sử, ước lượng còn nhớ, số ngày từ lần dùng cuối, liên quan tới kỳ thi nào, mức khẩn. Và bạn có quyền không đồng ý. Nemo12 gợi ý; gia đình quyết định. &quot;Học&quot;, &quot;đo&quot;, &quot;nghỉ&quot; không phải ba mức độ nghiêm khắc khác nhau. Chúng là ba câu trả lời cho ba tình huống thông tin khác nhau. <a href="/decisions/khac-goi-y">Vì sao hai bạn cùng tuổi nhận gợi ý khác nhau →</a></p>',17)])])}const s=h(a,[["render",c]]);export{q as __pageData,s as default};
